impl Mirror for HitResult {
    const SIZE: u32 = 0x24;

    fn import(m: &Mem, at: u32, cx: &mut dyn Cx) -> Self {
        let _ = (&m, at, &cx);
        HitResult {
            bone: cx.import_handle("JObjId", m.u32(at + 0x0)).map(JObjId),
            skip_update_pos: m.bits(at, 32, 1) != 0,
            pos: Vec3::import(m, at + 0x8, cx),
            offset: Vec3::import(m, at + 0x14, cx),
            size: f32::from_bits(m.u32(at + 0x20)),
        }
    }

    fn compare(&self, m: &Mem, at: u32, path: &str, cx: &mut dyn Cx) {
        let _ = (&m, at, path, &cx);
        cx.compare_handle(
            &format!("{path}.bone"),
            "JObjId",
            self.bone.map(|h| h.0),
            m.u32(at + 0x0),
        );
        if (self.skip_update_pos as u32) != m.bits(at, 32, 1) {
            cx.mismatch(
                &format!("{path}.skip_update_pos"),
                format!("{:?}", self.skip_update_pos),
                format!("{:?}", m.bits(at, 32, 1)),
            );
        }
        self.pos.compare(m, at + 0x8, &format!("{path}.pos"), cx);
        self.offset
            .compare(m, at + 0x14, &format!("{path}.offset"), cx);
        if self.size.to_bits() != m.u32(at + 0x20) {
            cx.mismatch(
                &format!("{path}.size"),
                format!("{:?}", self.size),
                format!("{:?}", f32::from_bits(m.u32(at + 0x20))),
            );
        }
    }
}

